def closure(requested, dependencies):
    found, pending = set(), list(requested)
    while pending:
        node = pending.pop()
        if node in found:
            continue
        if node not in dependencies:
            raise ValueError('unknown dependency')
        found.add(node)
        pending.extend(dependencies[node])
    return found

