import heapq
from graph import closure
def plan(requested, dependencies):
    nodes = closure(requested, dependencies)
    remaining = {node:len(set(dependencies[node])) for node in nodes}
    consumers = {node:[] for node in nodes}
    for node in nodes:
        for dep in set(dependencies[node]):
            consumers[dep].append(node)
    ready = [node for node in nodes if not remaining[node]]
    heapq.heapify(ready)
    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for consumer in consumers[node]:
            remaining[consumer] -= 1
            if not remaining[consumer]: heapq.heappush(ready, consumer)
    if len(result) != len(nodes):
        raise ValueError('cycle in requested closure')
    return result
